<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Escáner SAE</title></head><body><h1>Registrar asistencia</h1><form id="scanner">@csrf<label>Clase <select name="clase_profesor_id" required>@foreach($clases as $c)<option value="{{$c->id}}">{{$c->materia->nombre}} — {{$c->grado->nombre}} {{$c->seccion->nombre}}</option>@endforeach</select></label><br><label>Token QR <input name="qr_token" required autofocus></label><button>Verificar</button></form><p id="resultado" role="status"></p><script>document.querySelector('#scanner').addEventListener('submit',async e=>{e.preventDefault();let r=await fetch(@json(route('profesor.verificar')),{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':e.target._token.value},body:new FormData(e.target)});let d=await r.json();document.querySelector('#resultado').textContent=d.message;if(r.ok)e.target.qr_token.value='';});</script></body></html>
